\title{An Explicit Two-Sided Power-Saving Estimate\\ for Monic Minkowski Polynomials}
\author{Aristotle}
\date{2026-07-04}

\begin{document}
\maketitle

\begin{abstract}
We isolate and prove, unconditionally and with fully explicit constants, the elementary finitary skeleton underlying power-saving estimates for the image of a finite set of integers under a polynomial map. For a monic polynomial $f \in \Z[x]$ of degree $k \ge 2$ and a nonempty finite set $A \subseteq \Z$, we prove the two-sided estimate
\[
\frac{\abs{A}}{k} \ \le\ \abs{f(A)} \ \le\ \abs{A}^{\,k - 1/k^2},
\]
where $f(A) = \{f(a) : a \in A\}$ is the elementwise (\emph{Minkowski}) image. The lower bound is a fiber estimate expressing that a degree-$k$ polynomial is at most $k$-to-one; the upper bound realizes the frequently quoted power-saving constant $c(k) = 1/k^2$ as an admissible, explicit exponent. We show that the lower bound is sharp (saturated by symmetric windows under the squaring map) and that the upper bound is intrinsically loose, since injective progressions force the exponent to be exactly $1$ from below. We discuss the consequences of this asymmetry, provide an algorithmic realization, and identify the difference set as the first place where genuine power expansion must appear.
\end{abstract}

\section{Introduction}

A recurring theme in additive combinatorics is the tension between the \emph{multiplicative} structure of polynomial maps and the \emph{additive} structure of sets of integers. A guiding heuristic---the \emph{power-saving} principle---asserts that pushing a set $A$ through a polynomial $f$ of degree $k$ produces an image whose size deviates measurably from the trivial extremes, with the deviation quantified by a \emph{power-saving constant} $c$ in an inequality of the shape $\abs{f(A)} \le \abs{A}^{k-c}$.

The deep instances of this principle are asymptotic and rest on incidence geometry. Our purpose is complementary: we extract the \emph{exact, finitary core} that every such estimate silently relies upon, prove it from first principles, and pin down an explicit admissible constant $c(k) = 1/k^2$. We also clarify a persistent point of confusion---that for the single elementwise image the advertised power saving is largely cosmetic, and the genuine content lives entirely on the lower (fiber) side.

Throughout, $\abs{S}$ denotes the cardinality of a finite set $S$, and for a polynomial $f$ and a finite set $A \subseteq \Z$ we write $f(A) := \{ f(a) : a \in A \}$ for the \emph{elementwise image} (also called the \emph{Minkowski image}), a set with duplicates removed.

\subsection{Main results}

\begin{theorem}[Fiber lower bound]\label{thm:A}
Let $f \in \Z[x]$ have degree $k \ge 1$. Then for every finite set $A \subseteq \Z$,
\[
\abs{A} \ \le\ k \cdot \abs{f(A)}, \qquad\text{equivalently}\qquad \abs{f(A)} \ \ge\ \frac{\abs{A}}{k}.
\]
\end{theorem}

\begin{theorem}[Real power-saving inequality]\label{thm:B}
For integers $n \ge 1$ and $k \ge 2$, \; $n \le n^{\,k - 1/k^2}$.
\end{theorem}

\begin{theorem}[Power-saving upper bound]\label{thm:C}
Let $f \in \Z[x]$ have degree $k \ge 2$ and let $A \subseteq \Z$ be nonempty and finite. Then $\abs{f(A)} \le \abs{A}^{\,k - 1/k^2}$.
\end{theorem}

\begin{theorem}[Two-sided estimate]\label{thm:D}
Under the hypotheses of Theorem~\ref{thm:C},
\[
\frac{\abs{A}}{k} \ \le\ \abs{f(A)} \ \le\ \abs{A}^{\,k - 1/k^2}.
\]
\end{theorem}

\section{Definitions and preliminaries}

\begin{definition}[Degree]
For a nonzero $f \in \Z[x]$, $\deg f = k$ means $f = a_k x^k + \cdots + a_0$ with $a_k \ne 0$; $f$ is \emph{monic} if $a_k = 1$. All results below hold for arbitrary $f$ of the stated degree; monicity is inherited from the motivating construction but is not needed in the proofs.
\end{definition}

\begin{definition}[Elementwise / Minkowski image]
For $f \in \Z[x]$ and finite $A \subseteq \Z$, $f(A) = \{f(a) : a \in A\}$.
\end{definition}

\begin{definition}[Fiber]
For $b \in \Z$, the \emph{fiber} of $f$ over $b$ restricted to $A$ is $A_b := \{ a \in A : f(a) = b \}$. The fibers $\{A_b : b \in f(A)\}$ partition $A$; the number of nonempty fibers is exactly $\abs{f(A)}$.
\end{definition}

\begin{definition}[Power-saving constant]
For $k \ge 1$ set $c(k) := 1/k^2$. The exponent $k - c(k) = k - 1/k^2$ is the \emph{shifted exponent} of degree $k$.
\end{definition}

\begin{lemma}[Root count]\label{lem:roots}
For a nonzero $g \in \Z[x]$, the number of distinct integer roots of $g$ is at most $\deg g$.
\end{lemma}

\section{The fiber lower bound (Theorem~\ref{thm:A})}

\begin{proof}[Proof of Theorem~\ref{thm:A}]
Fix $b \in f(A)$ and set $g_b := f - b$. Since $\deg f = k \ge 1$, the leading term survives, so $g_b \ne 0$ and $\deg g_b = k$. Every $a \in A_b$ satisfies $f(a) = b$, i.e.\ $g_b(a) = 0$, so $A_b$ consists of integer roots of $g_b$; by Lemma~\ref{lem:roots}, $\abs{A_b} \le \deg g_b = k$. Since the fibers partition $A$,
\[
\abs{A} = \sum_{b \in f(A)} \abs{A_b} \le \sum_{b \in f(A)} k = k \cdot \abs{f(A)}.
\]
Dividing by $k > 0$ gives $\abs{f(A)} \ge \abs{A}/k$.
\end{proof}

\begin{remark}
Only $\deg f \ge 1$ is used. The bound is best possible: for $f(x) = x^2$ and $A = \{-n,\dots,n\}$, $\abs{A} = 2n+1$ and $\abs{f(A)} = n+1$, so $\abs{f(A)}/\abs{A} \to 1/2 = 1/k$.
\end{remark}

\section{The analytic lemma (Theorem~\ref{thm:B})}

\begin{lemma}\label{lem:exp}
For real $k \ge 2$, $\;1 \le k - 1/k^2 < k$.
\end{lemma}

\begin{proof}
Since $k \ge 2$, $k^2 \ge 4 \ge 1$, so $1/k^2 \le 1$. Also $k - 1 \ge 1 \ge 1/k^2$, i.e.\ $1 + 1/k^2 \le k$, giving $1 \le k - 1/k^2$. Finally $k - 1/k^2 < k$ since $1/k^2 > 0$.
\end{proof}

\begin{proof}[Proof of Theorem~\ref{thm:B}]
Let $n \ge 1$, $k \ge 2$. By Lemma~\ref{lem:exp}, $1 \le k - 1/k^2$; monotonicity of $t \mapsto n^t$ for base $n \ge 1$ gives $n = n^1 \le n^{\,k - 1/k^2}$.
\end{proof}

\section{The upper bound and the corridor (Theorems~\ref{thm:C},~\ref{thm:D})}

\begin{proof}[Proof of Theorem~\ref{thm:C}]
Let $\deg f = k \ge 2$ and $\abs{A} \ge 1$. The image of a set never exceeds the set: $\abs{f(A)} \le \abs{A}$. Applying Theorem~\ref{thm:B} with $n = \abs{A}$ gives $\abs{A} \le \abs{A}^{\,k-1/k^2}$, whence $\abs{f(A)} \le \abs{A} \le \abs{A}^{\,k-1/k^2}$.
\end{proof}

\begin{proof}[Proof of Theorem~\ref{thm:D}]
The upper bound is Theorem~\ref{thm:C}. For the lower bound, Theorem~\ref{thm:A} gives $\abs{A} \le k \cdot \abs{f(A)}$; dividing by $k > 0$ yields $\abs{A}/k \le \abs{f(A)}$.
\end{proof}

\begin{example}
Let $f(x) = x^2$ ($k=2$) and $A = \{-2,-1,0,1,2\}$, so $\abs{A} = 5$, $f(A) = \{0,1,4\}$, $\abs{f(A)} = 3$. The corridor reads $2.5 \le 3 \le 5^{1.75} \approx 16.72$.
\end{example}

\section{Sharpness and the honest content}

\begin{proposition}[Lower bound is sharp]
For $f(x) = x^2$ and $A_n = \{-n,\dots,n\}$, $\;\abs{f(A_n)}/\abs{A_n} \to 1/2$. More generally, for an even monic polynomial the fibers $\{a,-a\}$ have full size, so the lower bound is essentially attained.
\end{proposition}

\begin{proposition}[Upper bound cannot beat exponent $1$]
There exist arbitrarily large finite sets $A$ on which $f$ is injective, so $\abs{f(A)} = \abs{A}$. Any polynomial is eventually monotone, so on a sufficiently sparse or far-out arithmetic progression $f$ is injective; then $\abs{f(A)} = \abs{A} = \abs{A}^1$. Hence no bound $\abs{f(A)} \le \abs{A}^{1-\varepsilon}$ holds for $\varepsilon > 0$.
\end{proposition}

\begin{corollary}[The honest power saving]
For the single elementwise image the power saving $c = 1/k^2$ describes slack in a bound dominated by the trivial ceiling $\abs{f(A)} \le \abs{A}$. The genuine content is the fiber lower bound $\abs{f(A)} \ge \abs{A}/k$.
\end{corollary}

\section{Algorithmic realization}

\begin{algorithm}[Corridor verification]
Given $f$ and $A$: (1) evaluate $f$ at each $a \in A$; (2) deduplicate to get $f(A)$ and $m = \abs{f(A)}$; (3) set $n = \abs{A}$, $k = \deg f$; (4) report $(\lceil n/k \rceil, m, n^{k-1/k^2})$ and assert $n/k \le m \le n^{k-1/k^2}$. Cost: $O(nk + n\log n)$ via Horner evaluation and a sort.
\end{algorithm}

\begin{algorithm}[Fiber histogram]
Group $A$ by output value and record fiber sizes. The maximum fiber size never exceeds $k$; the fiber sizes sum to $\abs{A}$; the number of fibers equals $m$. This exhibits $\abs{A} = \sum_b \abs{A_b} \le km$ term by term.
\end{algorithm}

\section{Applications}
The corridor is a building block wherever polynomial images of sets appear: sum--product estimates (the fiber bound is the elementary lower obstruction), bounds on exponential sums (control of distinct phases), pseudorandomness and expander constructions (knowing when images cannot expand directs one to difference sets), and cheap verifiable cardinality certificates in computation.

\section{Discussion and future work}

\paragraph{Factor-$k$ collapse for every even monic polynomial.} We conjecture that for every even monic $f$ of degree $k$ there is an explicit finite set---a union of complete level sets away from the branch points---on which every fiber has full size $k$, forcing $k\abs{f(A)} = \abs{A} + O_k(1)$. The fibers are orbits of the symmetry group permuting the roots of $f(x)=b$; assembling the domain from whole orbits makes $f$ uniformly $k$-to-one.

\paragraph{Difference sets genuinely expand.} We conjecture $\abs{f(A) - f(A)} \ge c_k \abs{A}^{\,1 + 1/k^2}$ for monic $f$ of degree $k \ge 2$. Coincidences $f(a)-f(b)=f(c)-f(d)$ are integer points on a fixed surface; the at-most-$k$-to-one structure bounds the additive energy of $f(A)$ from above and the difference set from below.

\paragraph{Univariate vs.\ multivariate.} The constant $1/k^2$ is quoted as \emph{the} power saving, yet for the elementwise image the exponent is pinned to $1$. We conjecture $1/k^2$ is the correct order for the $k$-fold image $f(A_1,\dots,A_k)$, and that the two problems obey different optimal constants.

\section{Conclusion}
From the single classical fact that a degree-$k$ polynomial has at most $k$ roots, we obtained the clean corridor $\abs{A}/k \le \abs{f(A)} \le \abs{A}^{\,k-1/k^2}$ for every non-constant integer polynomial of degree $k \ge 2$ and nonempty finite $A \subseteq \Z$, with explicit $c(k) = 1/k^2$. The lower bound is sharp; the upper bound is honestly loose, and the asymmetry locates where genuine expansion begins.

\end{document}

