from collections import Counter
from typing import Dict, List, Sequence


def eval_poly(coeffs: Sequence[int], x: int) -> int:
    """Horner evaluation; coeffs highest-degree-first: [a_k,...,a_0]."""
    acc = 0
    for c in coeffs:
        acc = acc * x + c
    return acc


def degree(coeffs: Sequence[int]) -> int:
    for i, c in enumerate(coeffs):
        if c != 0:
            return len(coeffs) - 1 - i
    raise ValueError("zero polynomial")


def corridor(coeffs: Sequence[int], A: Sequence[int]) -> Dict[str, float]:
    """Compute lower bound |A|/k, actual |f(A)|, upper bound |A|^(k-1/k^2)."""
    k = degree(coeffs)
    n = len(set(A))
    m = len({eval_poly(coeffs, a) for a in A})
    lower = n / k
    upper = float(n) ** (k - 1.0 / (k * k))
    return {"n": n, "k": k, "image_size": m,
            "lower": lower, "upper": upper,
            "holds": lower <= m <= upper + 1e-9}


if __name__ == "__main__":
    A = list(range(-6, 7))
    for name, coeffs in [("x^2", [1, 0, 0]), ("x^3", [1, 0, 0, 0]),
                         ("x^4 - 5x^2 + 4", [1, 0, -5, 0, 4])]:
        info = corridor(coeffs, A)
        print(name, info)

from typing import List, Sequence


def image_size(coeffs: Sequence[int], A: Sequence[int]) -> int:
    def ev(x: int) -> int:
        acc = 0
        for c in coeffs:
            acc = acc * x + c
        return acc
    return len({ev(a) for a in A})


def collapse_ratios(max_n: int) -> List[float]:
    """|f(A)|/|A| for f = x^2 on {-n,...,n}; converges to 1/k = 1/2."""
    ratios = []
    for n in range(1, max_n + 1):
        A = list(range(-n, n + 1))
        ratios.append(image_size([1, 0, 0], A) / len(A))
    return ratios


if __name__ == "__main__":
    r = collapse_ratios(500)
    print("n=10 ratio :", r[9])
    print("n=100 ratio:", r[99])
    print("n=500 ratio:", r[499], "-> 1/2")

